window.DM_SABLONLAR = {"guvenlik":[{"ad":"Arka Deltoid (Omuz arka lifi) — güvenlik","metin":"Öne eğilip yana açma hareketlerinde beli yuvarlamak yükü bele taşır. Kalçadan menteşe yap, sırtı düz tut; hafif yükle çalış, hız yerine kontrol.","kaynak":"admin-anatomi-form.html","m":"fit"},{"ad":"Arka Uyluk Kasları (Hamstring) — güvenlik","metin":"Hamstring zorlanması en sık, kas soğukken veya yorgunken hızlı gerilme anında olur. Salınım hareketlerinde dizi kilitleme, hafif bükülü tut; ısınmadan maksimum açıklıkta öne eğilme yapma.","kaynak":"admin-anatomi-form.html","m":"fit"},{"ad":"Bel ve Sırt Dikleştiricileri — güvenlik","metin":"Delavier deadlift sayfasında üç maddelik açık uyarı veriyor (PDF s. 79): ağır yükte nefesi göğüste tut, karnı ger, bel bölgesindeki kasları kasarak omurgayı düzleştir — bu üçü bel fıtığı riskini azaltır. Yuvarlak belle ağırlık kaldırma; salınım hareketlerini kalçadan üret, belden değil.","kaynak":"admin-anatomi-form.html","m":"fit"},{"ad":"Biceps (İki başlı kol kası) — güvenlik","metin":"Curl'de gövdeyi sallayıp beli hiperekstansiyona sokmak biceps'ten yükü alır, bele verir. Dirseği gövde yanında sabitle, yükü indirirken tam gerilmeye zorlanmadan kontrollü bırak.","kaynak":"admin-anatomi-form.html","m":"fit"},{"ad":"Boyun (Baş çevirici) — güvenlik","metin":"Boyun kasları yük kaldırmak için değil, başı taşımak için tasarlanmıştır. Kürek çekerken ya da plank'ta çeneyi öne uzatıp boynu geriye kırma; kulak–omuz hizasını koru. Ağırlıkla doğrudan boyun çalıştırmak prototip kapsamı dışıdır.","kaynak":"admin-anatomi-form.html","m":"fit"},{"ad":"Brachioradialis (Dirsek altı bükücü) — güvenlik","metin":"Ön kol kasları küçük ve hızlı yorulur; ağır tutuş gerektiren hareketlerde bileği geriye kırmadan nötr tut. Dirsek dış tarafında yanıcı ağrı (tenisçi dirseği) varsa tutuş çalışmasını artırma, dinlendir ve uzmana danış.","kaynak":"admin-anatomi-form.html","m":"fit"},{"ad":"Büyük Kalça Kası — güvenlik","metin":"Köprü ve kalça itişinde hareketi belden hiperekstansiyonla bitirmek yaygın hatadır. Kaburgaları aşağıda tut, karnı hafif ger, hareketi kalçayı sıkarak bitir — bel değil kalça yükselsin.","kaynak":"admin-anatomi-form.html","m":"fit"},{"ad":"Büyük Yuvarlak Kas — güvenlik","metin":"Koltuk altı bölgesi çekme hareketlerinde kolayca gerilir. Çekişte omzu kulaktan uzak tut; hareketin sonunda kolu aşırı arkaya zorlayıp omuz ön kapsülünü açma.","kaynak":"admin-anatomi-form.html","m":"fit"},{"ad":"Dört Başlı Uyluk Kası (Ön bacak) — güvenlik","metin":"Çömelmede dizin içe düşmesi (valgus) diz kapağı hizasını bozar. Ayak tabanının üç noktasına bas, dizi ayak orta parmağı yönünde tut; topuğu yerden kesme.","kaynak":"admin-anatomi-form.html","m":"fit"},{"ad":"Düz Karın Kası (Six-pack) — güvenlik","metin":"Delavier bu bölümü bir UYARI kutusuyla açıyor (PDF s. 117): bel şikâyeti olanlarda karın çalışırken kalçanın sabitlenmesi şart, çünkü bel kası (psoas) beli içe çukurlaştırıp omur sorunlarına yol açabilir. Karnı gererek değil, kısa mesafede kontrollü çalış; boyun elle çekilmez.","kaynak":"admin-anatomi-form.html","m":"fit"},{"ad":"Fasya Lata Gerici (Kalça yan gerici) — güvenlik","metin":"Kısalmış TFL, dizin dış yanında iliotibial bant ağrısına katkı verir. Kalça yan çalışmasını yalnız bu kasa bırakma — gluteus medius'u da hedefleyen tek bacak hareketleri dengeyi kurar.","kaynak":"admin-anatomi-form.html","m":"fit"},{"ad":"Geniş Sırt Kası — güvenlik","metin":"Tek kol kürek çekerken gövdeyi çekiş yönünde döndürmek beli burar. Gövdeyi sabit tut, hareketi omuz ekleminden üret; ağırlığı sırt yerine bel ile kaldırma.","kaynak":"admin-anatomi-form.html","m":"fit"},{"ad":"Göğüs (Büyük göğüs kası) — güvenlik","metin":"Şınavda göğsü çok derine indirip omuz başını öne kaydırmak kapsül ve rotator manşeti zorlar. Kürek kemiklerini geride tut, dirsekleri gövdeye 45° civarında yaklaştır — 90°'lik \"T\" duruşu omuza yüklenir.","kaynak":"admin-anatomi-form.html","m":"fit"},{"ad":"İç Uyluk Kasları (Toplayıcılar) — güvenlik","metin":"Soğuk kasla geniş açıklıkta yana açılma iç uyluk zorlanmasının en sık nedenidir. Geniş duruşlu çömelmede açıklığı kalçanın izin verdiği kadar tut; ısınmadan derin esnetme yapma.","kaynak":"admin-anatomi-form.html","m":"fit"},{"ad":"İkiz Baldır Kası (Dış baldır) — güvenlik","metin":"Aşil tendonu ani hızlanma ve zıplamalarda risk altındadır. Baldır çalışmasında son noktada zıplayarak sekme; hareketi kontrollü indir, tam açıklıkta zorlamadan çalış.","kaynak":"admin-anatomi-form.html","m":"fit"},{"ad":"Kalça Bükücü (Bel-uyluk kası) — güvenlik","metin":"Delavier'in karın bölümü uyarısı doğrudan bu kası hedef alıyor (PDF s. 117): bel ağrısı olanlarda psoas beli içe çukurlaştırır. Uzun oturan biri için kısalmış olması beklenir — mekik yerine dead bug gibi bel nötr kalan hareketleri tercih et.","kaynak":"admin-anatomi-form.html","m":"fit"},{"ad":"Nalımsı Kas (Derin baldır) — güvenlik","metin":"Soleus kısalığı bilek hareketliliğini kısıtlar ve çömelmede topuğun yerden kalkmasına yol açar. Dizi bükerek yapılan baldır esnetmesini rutine ekle; ağrı varsa açıklığı zorlama.","kaynak":"admin-anatomi-form.html","m":"fit"},{"ad":"Orta Kalça Kası (Yan kalça) — güvenlik","metin":"Tek bacak hareketlerinde kalçanın yana açılıp gövdenin karşı tarafa yatması bu kasın yetişemediğini gösterir. Hamlede leğen kemiğini yere paralel tut; adımı kısaltıp kontrolü koru.","kaynak":"admin-anatomi-form.html","m":"fit"},{"ad":"Orta ve Alt Trapez — güvenlik","metin":"Kürek çekerken hareketi yalnız kolla yapıp kürek kemiklerini hareketsiz bırakmak orta trapezi devre dışı bırakır. Çekişi kürek kemiklerini geri-aşağı kaydırarak başlat, omuzları kulağa doğru kaldırma.","kaynak":"admin-anatomi-form.html","m":"fit"},{"ad":"Ön Baldır Kası — güvenlik","metin":"Ön baldır ağrısı (\"shin splint\") çoğunlukla ani mesafe artışından gelir. Yürüyüş/koşu hacmini haftada belirgin sıçramalarla değil kademeli artır; çömelmede topuk yükseltmeye ihtiyaç duyuyorsan bilek hareketliliğini ayrıca çalış.","kaynak":"admin-anatomi-form.html","m":"fit"},{"ad":"Ön Deltoid (Omuz ön lifi) — güvenlik","metin":"Ön deltoid itme hareketlerinde zaten çok iş alır; arka lif ihmal edilirse omuz öne yuvarlanır. Presi ense arkasına indirme, dirseği gövdeden 90°'den fazla açma.","kaynak":"admin-anatomi-form.html","m":"fit"},{"ad":"Ön Dişli Kas (Kaburga tarağı) — güvenlik","metin":"Plank ve şınavda kürek kemiklerinin sırtta \"kanat\" gibi kalkması serratus'un devrede olmadığını gösterir. Kolları yere itip göğsü hafif yukarı ittir; bel çökmesin.","kaynak":"admin-anatomi-form.html","m":"fit"},{"ad":"Ön Kol Açıcıları (Dış ön kol) — güvenlik","metin":"Dış dirsek ağrısı (\"tenisçi dirseği\") bu grubun ortak başlangıç tendonundan gelir. Ağırlığı kavrarken bileği geriye kırma; ağrı varsa ters kavrama (avuç içi yukarı) çalışmalarını azalt.","kaynak":"admin-anatomi-form.html","m":"fit"},{"ad":"Ön Kol Bükücüleri (İç ön kol) — güvenlik","metin":"Bileği aşırı bükerek ağırlık taşımak iç dirsek tendonunu zorlar. Bileği ön kolla aynı hizada nötr tut; kavrama tükendiğinde seti uzatma.","kaynak":"admin-anatomi-form.html","m":"fit"},{"ad":"Romboid Kaslar (Elmas kaslar) — güvenlik","metin":"Romboidler yorulduğunda üst trapez işi devralır ve omuzlar kulağa yaklaşır. Yükü hafifletip kürek kemiklerini AŞAĞI-geri kaydırmayı koru; iki kürek arasını \"sıkma\" hissi hedefin.","kaynak":"admin-anatomi-form.html","m":"fit"},{"ad":"Rotator Manşet (Omuz sarmalı) — güvenlik","metin":"Bu kaslar ağır yükle değil, düşük yük–yüksek kontrolle çalışır. Omuz ağrısı varken baş üstü itme ve ense arkası hareketlerden kaçın; bant ile dışa döndürme çalışmasını ısınmaya koy.","kaynak":"admin-anatomi-form.html","m":"fit"},{"ad":"Triceps (Üç başlı kol kası) — güvenlik","metin":"Dirseği kilitlenene kadar zorla itmek eklem yüzeyine yükler. Şınavda dirsekleri gövdeye yakın tut; ağırlığı başın arkasına indiren hareketlerde dirseği sabitle, omzu sallama.","kaynak":"admin-anatomi-form.html","m":"fit"},{"ad":"Üst Göğüs (Büyük göğüs kası, köprücük başı) — güvenlik","metin":"Üst göğsü hedefleyen eğik itişlerde eğim açısını abartma; 45°'nin üstünde yük göğüsten çıkıp ön deltoide geçer ve omuz önü zorlanır. Şınavda ayakları yükseltip aynı etkiyi ararken belin çökmesine izin verme.","kaynak":"admin-anatomi-form.html","m":"fit"},{"ad":"Üst Trapez (Kukuleta kası, üst lif) — güvenlik","metin":"Masa başı hayatında üst trapez zaten kısalmış ve aşırı çalışıyor olur. Omuz pres ve kürek çekmede omuzları kulağa doğru kaldırıp asma; kürek kemiklerini önce aşağı-geri yerleştir, sonra çek.","kaynak":"admin-anatomi-form.html","m":"fit"},{"ad":"Yan Deltoid (Omuz orta lifi) — güvenlik","metin":"Yana açarken kolu omuz hizasının belirgin üstüne çıkarmak ve baş parmağı aşağı çevirmek sıkışma yaratır. Hafif yükle, dirsek hafif bükülü, başparmak yukarı bakacak şekilde çalış.","kaynak":"admin-anatomi-form.html","m":"fit"},{"ad":"Yan Karın Kasları (Oblikler) — güvenlik","metin":"Elde ağırlıkla yana eğilme hareketleri beli sıkıştırabilir. Dönme hareketlerini bel omurundan değil, göğüs omurundan üret; leğen kemiği sabit kalsın.","kaynak":"admin-anatomi-form.html","m":"fit"}],"not":[{"ad":"Bazal Metabolizma Hızı (BMH) — not","metin":"Mifflin-St Jeor denklemi kullanılır: 10×kilo + 6.25×boy − 5×yaş; erkekte +5, kadında −161.","kaynak":"admin-hesaplayici-form.html","m":"diet"},{"ad":"Beden Kütle Endeksi (BKİ) — not","metin":"BKİ yalnızca boy ve kiloyu kullanır; aktivite kalori hesaplayıcıda devreye girer.","kaynak":"admin-hesaplayici-form.html","m":"diet"},{"ad":"Günlük Kalori İhtiyacı — not","metin":"Günlük ihtiyaç = BMH (Mifflin-St Jeor) × aktivite katsayısı.","kaynak":"admin-hesaplayici-form.html","m":"diet"},{"ad":"Günlük Su İhtiyacı — not","metin":"Taban ihtiyaç: kilo × 35 ml (TÜBER 2022, §2.2.7). Egzersiz yaptığın günlerde her saat için ek su gerekir; sıcak hava ve gebelik/emzirme dönemlerinde ihtiyaç artar.","kaynak":"admin-hesaplayici-form.html","m":"diet"},{"ad":"Hedef Kiloya Ulaşma Süresi — not","metin":"Boş bırakırsan bugünden başlar. 1 kg yağ yaklaşık 7.700 kcal karşılığı kabul edilir; günlük fark bu değerden türetilir.","kaynak":"admin-hesaplayici-form.html","m":"diet"},{"ad":"İdeal Kilo — not","metin":"Devine formülü kullanılır: erkekte 50 kg, kadında 45.5 kg taban + 152 cm (60 inç) üzerindeki her inç için 2.3 kg. Aralık, BKİ 18.5-24.9 bandının boyuna karşılığıdır.","kaynak":"admin-hesaplayici-form.html","m":"diet"},{"ad":"Makro Dağılımı — not","metin":"Değerler vücut ağırlığı başına gram (g/kg) genel aralıklarından türetilir — protein, karbonhidrat ve yağ ayrı ayrı. Toplam kalori hesaplanmaz.","kaynak":"admin-hesaplayici-form.html","m":"diet"},{"ad":"Porsiyon Hesaplama — not","metin":"Çarpan = (hedef kişi ÷ tarif kişi) × porsiyon boyutu. Tüm malzemeleri bu çarpanla çarparak ölçekle. Pişirme süresi ve baharatı orantıyla değil, tada göre ayarla.","kaynak":"admin-hesaplayici-form.html","m":"diet"},{"ad":"Vücut Tipi (Bel/Kalça) — not","metin":"Bel çevreni göbek deliği hizasından, kalçanı en geniş noktasından mezurayla ölç. Oran = bel ÷ kalça; yağının vücuduna nasıl dağıldığını gösterir.","kaynak":"admin-hesaplayici-form.html","m":"diet"},{"ad":"Vücut Yağ Oranı — not","metin":"ABD Donanması (U.S. Navy) çevre ölçüsü yöntemi kullanılır. Bel ölçüsü kadınlarda en dar noktadan, erkeklerde göbek deliği hizasından; boyun ölçüsü gırtlağın hemen altından alınır. Mezura teni sıkmadan, düz durur.","kaynak":"admin-hesaplayici-form.html","m":"diet"}]};
